CREATE TABLE peniel_ops.caravan_requests (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, request_id uuid NOT NULL UNIQUE, session_date date NOT NULL CHECK (session_date IN ('2026-11-09','2026-11-13','2026-11-14','2026-11-19','2026-11-20','2026-11-21')), payload jsonb NOT NULL CHECK (jsonb_typeof(payload)='object'), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','imported')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz, reviewed_by uuid REFERENCES peniel_ops.staff(user_id), caravan_id uuid, review_reference text, CHECK ((status='pending' AND reviewed_at IS NULL AND reviewed_by IS NULL AND caravan_id IS NULL) OR (status='imported' AND reviewed_at IS NOT NULL AND reviewed_by IS NOT NULL AND caravan_id IS NOT NULL AND review_reference IS NOT NULL))); ALTER TABLE peniel_ops.caravan_requests ENABLE ROW LEVEL SECURITY; REVOKE ALL ON peniel_ops.caravan_requests FROM PUBLIC, anon, authenticated; CREATE INDEX caravan_requests_pending_idx ON peniel_ops.caravan_requests (session_date,created_at) WHERE status='pending';
